import raw from '@/data/catalog.json';
import {rankCatalog,interpretQuery,type SearchOptions} from './catalog-search';
export type Feature={name:string;description:string;status:'supported'|'conditional'|'unknown';condition:string;sourceUrl:string};
export type Tool={id:string;name:string;kind:'ai-app'|'model'|'saas';vendor:string;category:string;summary:string;description:string;homepage:string;logo:string;logoSource:string;logoNote?:string;aliases?:string[];pricing:string;korean:string;platforms:string[];useCases:string[];features:Feature[];limitations:string[];sourceUrls:string[];checkedAt:string;latestUpdate:{title:string;summary:string;publishedAt:string|null;sourceUrl:string;audience?:string;rollout?:string};feedScope?:string;feedUrl?:string};
export const catalog=raw as Tool[];
export const categories:Record<string,string>={all:'전체',research:'리서치',writing:'문서·글쓰기',image:'디자인·이미지',development:'개발',productivity:'생산성',automation:'자동화'};
export const kindLabels:Record<string,string>={'ai-app':'AI 앱',model:'AI 모델',saas:'SaaS'};
export function findTool(id:string){return catalog.find(t=>t.id===id);}
export function relatedTools(tool:Tool){return catalog.filter(t=>t.id!==tool.id&&t.kind===tool.kind).map(t=>({tool:t,weight:Number(t.category===tool.category)*3+t.useCases.filter(u=>tool.useCases.includes(u)).length})).sort((a,b)=>b.weight-a.weight).slice(0,2).map(t=>t.tool);}
export function searchCatalog(query:string,options:SearchOptions={}){return rankCatalog(catalog,query,options);}
export function interpretCatalogQuery(query:string){return interpretQuery(query,catalog);}

